using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appBuilder = null!;
    private static DistributedApplication _app = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appBuilder.BuildAsync();
        await _app.StartAsync();

        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(chatClient),
            storageRootPath: Path.Combine(context.TestRunResultsDirectory ?? ".", "eval-results"));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.StopAsync();
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(nameof(GreetingResponse_IsCoherentAndRelevant));

        var chatClient = _app.Services.GetRequiredService<IChatClient>();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello! Can you introduce yourself briefly?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndFluent()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(nameof(FactualQuestion_IsGroundedAndFluent));

        var chatClient = _app.Services.GetRequiredService<IChatClient>();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France? Answer in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(nameof(MultiTurnConversation_MaintainsCoherence));

        var chatClient = _app.Services.GetRequiredService<IChatClient>();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan. What should I know?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What about the food there?"));
        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();
    }
}

